contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(this); }

    // single public test function taking inputs: caller flag and newOwner
    // If asAdmin == true we simulate calling setOwner as the admin by calling directly (the contract InvMutTest is the deployer/admin of C).
    // If asAdmin == false we attempt to call setOwner via a low-level call from a different address by using delegatecall-like pattern
    // but since we cannot change msg.sender for external calls, we instead rely on calling from this contract always.
    // To test non-admin behavior we attempt to call setOwner through a call triggered from a payable fallback: we create a short-lived helper by using call to address(c) with malformed data
    // However solidity tests must only call c's public functions directly; to check revert for non-admin we use try/catch with an address that is not admin by deploying another contract is not allowed.
    // Simpler approach: observe that InvMutTest is the admin (deployer). We assert that when this contract calls setOwner it returns true and owner equals the provided address.
    // And we additionally assert that if the provided newOwner equals address(0) it is still settable (no restriction in C).

    function run(address newOwner) public payable {
        require(true);

        // Call setOwner as admin (this contract is admin since it deployed C)
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Read owner after the call
        address observedOwner = c.owner();

        // General rule: when admin calls setOwner it must succeed (return true) and owner becomes the given address.
        // Because this test contract deployed C, it is the admin; therefore ok must be true and observedOwner == newOwner.
        assert(ok == true && observedOwner == newOwner);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address newOwner, uint256 sendAmount) public payable {
        // ensure we have enough balance if we plan to send Ether (we won't send Ether to c here,
        // but include the standard guard in case inputs attempt to require it)
        require(address(this).balance >= sendAmount);

        // Observe balance before
        uint256 balBefore = address(c).balance;

        // Call setOwner and record whether it reverted and the returned value (if any)
        bool reverted;
        bool retval;
        try c.setOwner{value: 0}(newOwner) returns (bool r) {
            reverted = false;
            retval = r;
        } catch {
            reverted = true;
            retval = false;
        }

        // Read the public owner after the call
        address observedOwner = c.owner();

        // General rule asserted for all inputs:
        // If call reverted, owner must remain equal to observedOwner (no guaranteed change - but specifically,
        // when it reverts owner must not be equal to newOwner as an effect of the failed call unless it already was),
        // and contract balance must be unchanged. If call succeeded, it must have returned true and owner must equal newOwner,
        // and contract balance must be unchanged. Combine these into a single assert.
        assert(
            // balance unchanged always
            address(c).balance == balBefore
            && (
                // either it reverted and owner is unchanged relative to what a successful call would not have achieved here
                (reverted && (observedOwner != newOwner || (observedOwner == newOwner && retval == false)))
                // or it succeeded: returned true and owner equals newOwner
                || (!reverted && retval == true && observedOwner == newOwner)
            )
        );
    }

    // allow receiving Ether if needed by the test harness
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address newOwner) public payable {
        // Observe balance and owner before
        uint256 balBefore = address(c).balance;
        address ownerBefore = c.owner();

        // Call setOwner and record whether it reverted and the returned value (if any)
        bool reverted;
        bool retval;
        try c.setOwner(newOwner) returns (bool r) {
            reverted = false;
            retval = r;
        } catch {
            reverted = true;
            retval = false;
        }

        // Read the public owner after the call
        address observedOwner = c.owner();

        // General rule asserted for all inputs:
        // - balance is unchanged
        // - if call succeeded: returned true and owner == newOwner
        // - if call reverted: owner unchanged
        assert(
            address(c).balance == balBefore
            && (
                (!reverted && retval == true && observedOwner == newOwner)
                || (reverted && observedOwner == ownerBefore)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an arbitrary address and driving c
    function run(address newOwner) public payable {
        // record observable before-values
        address beforeOwner = c.owner();
        uint256 beforeBal = address(c).balance;

        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();
        uint256 afterBal = address(c).balance;

        // General rule: either call reverted and owner stayed as before, or it succeeded and owner equals newOwner;
        // also the contract balance must be unchanged.
        assert((reverted && afterOwner == beforeOwner || (!reverted && afterOwner == newOwner)) && afterBal == beforeBal);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller attempts to set owner and we check relation between revert flag and owner change
    function run(address newOwner) public payable {
        // read owner before
        address ownerBefore = c.owner();

        bool reverted;
        bool ret;
        // call setOwner and capture whether it reverted and returned value
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }

        address ownerAfter = c.owner();

        // General rule: call succeeds (didn't revert) iff owner changed to newOwner and returned true.
        // If it reverted then owner must remain ownerBefore.
        assert((!reverted && ret && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }

    receive() external payable {}
}
